+<?php
header('Content-Type: application/json');
require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/product_inventory.php';
try{$u=requireAuth();$uid=(int)$u->id;$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-d'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)||$to<$from)throw new Exception('Invalid date range');$conn=db();requireAnyPermission($conn,$uid,['stock.view','reports.view']);ensureProductInventorySchema($conn);$s=$conn->prepare("SELECT p.id,p.code,p.name,ROUND(SUM(m.cogs_value),3) cogs FROM product_stock_movements m JOIN products p ON p.id=m.product_id AND p.user_id=m.user_id WHERE m.user_id=? AND m.created_at>=? AND m.created_at<DATE_ADD(?,INTERVAL 1 DAY) GROUP BY p.id,p.code,p.name HAVING cogs<>0 ORDER BY cogs DESC");$s->bind_param('iss',$uid,$from,$to);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$total=array_reduce($rows,fn($v,$r)=>$v+(float)$r['cogs'],0.0);jsonResponse(['success'=>true,'valuation_method'=>'WEIGHTED_AVERAGE','from'=>$from,'to'=>$to,'total_cogs'=>round($total,3),'products'=>$rows]);}catch(Throwable $e){jsonResponse(['success'=>false,'message'=>$e->getMessage()],400);}
